import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { openDB } from 'idb';
import { supabase } from '../supabase';
import apiService from '../services/apiService';

// Create the context
const OfflineContext = createContext();

// Initialize IndexedDB
const initDB = async () => {
    return openDB('junctionOfflineDB', 1, {
        upgrade(db) {
            // Store for media files
            if (!db.objectStoreNames.contains('mediaFiles')) {
                db.createObjectStore('mediaFiles', {
                    keyPath: 'id',
                    autoIncrement: true
                });
            }
            // Store for pending uploads metadata
            if (!db.objectStoreNames.contains('pendingUploads')) {
                db.createObjectStore('pendingUploads', {
                    keyPath: 'id',
                    autoIncrement: true
                });
            }
        }
    });
};

// Function to convert file to base64
const fileToBase64 = async (file) => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve(reader.result);
        reader.onerror = (error) => reject(error);
    });
};

// Function to convert base64 to file
const base64ToFile = (base64String, fileName, type) => {
    const arr = base64String.split(',');
    const mime = arr[0].match(/:(.*?);/)[1];
    const bstr = atob(arr[1]);
    let n = bstr.length;
    const u8arr = new Uint8Array(n);

    while (n--) {
        u8arr[n] = bstr.charCodeAt(n);
    }

    return new File([u8arr], fileName, { type: type || mime });
};

// IndexedDB helpers for pending uploads
const addPendingUpload = async (db, upload) => {
    const tx = db.transaction('pendingUploads', 'readwrite');
    await tx.objectStore('pendingUploads').add(upload);
    await tx.done;
};

const getAllPendingUploads = async (db) => {
    const tx = db.transaction('pendingUploads', 'readonly');
    const items = await tx.objectStore('pendingUploads').getAll();
    await tx.done;
    return items;
};

const removePendingUploadById = async (db, id) => {
    const tx = db.transaction('pendingUploads', 'readwrite');
    await tx.objectStore('pendingUploads').delete(id);
    await tx.done;
};

export const OfflineProvider = ({ children }) => {
    const [isOffline, setIsOffline] = useState(!navigator.onLine);
    const [pendingUploads, setPendingUploads] = useState([]);
    const [db, setDb] = useState(null);
    const [isSyncing, setIsSyncing] = useState(false);

    // Initialize IndexedDB
    useEffect(() => {
        const setupDB = async () => {
            try {
                const database = await initDB();
                setDb(database);

                // Load pending uploads from IndexedDB
                const items = await getAllPendingUploads(database);
                setPendingUploads(items);
                console.log('Loaded pending uploads:', items.length);
            } catch (error) {
                console.error('Error initializing IndexedDB:', error);
            }
        };

        setupDB();
    }, []);

    // Monitor online/offline status
    useEffect(() => {
        const handleOnline = () => {
            setIsOffline(false);
            console.log('Back online. Attempting to sync...');
            syncPendingUploads();
        };

        const handleOffline = () => {
            setIsOffline(true);
            console.log('Device is offline. Changes will be synced later.');
        };

        window.addEventListener('online', handleOnline);
        window.addEventListener('offline', handleOffline);

        return () => {
            window.removeEventListener('online', handleOnline);
            window.removeEventListener('offline', handleOffline);
        };
    }, []);

    // Add to pending uploads (called when Mark as Done is clicked offline)
    const queueMediaUpload = async (donorId, { type, file, donorInfo }) => {
        if (!db) return;
        const upload = {
            id: `${donorId}_${type}_${Date.now()}`,
            donorId,
            type,
            file,
            donorInfo,
            status: 'pending'
        };
        await addPendingUpload(db, upload);
        const items = await getAllPendingUploads(db);
        setPendingUploads(items);
    };

    // Sync pending uploads when online
    const syncPendingUploads = useCallback(async () => {
        if (isOffline || !db || isSyncing || pendingUploads.length === 0) {
            return;
        }

        setIsSyncing(true);
        console.log(`Starting to sync ${pendingUploads.length} pending uploads`);

        try {
            for (const upload of pendingUploads) {
                try {
                    // Get the media file from IndexedDB
                    const mediaTx = db.transaction('mediaFiles', 'readonly');
                    const mediaStore = mediaTx.objectStore('mediaFiles');
                    const mediaFile = await mediaStore.get(upload.mediaId);

                    if (!mediaFile) {
                        console.error(`Media file not found for upload ${upload.id}`);
                        continue;
                    }

                    // Convert base64 back to file
                    const file = base64ToFile(
                        mediaFile.base64Data,
                        mediaFile.fileName,
                        mediaFile.fileType
                    );

                    // Upload to Supabase
                    const fileName = `${upload.donorId}_${upload.mediaType}_${Date.now()}_${Math.random().toString(36).substring(7)}`;
                    const filePath = `${upload.mediaType === 'image' ? 'images' : 'videos'}/${fileName}`;

                    const { data, error } = await supabase.storage
                        .from('media') // Verify this matches your bucket name exactly
                        .upload(filePath, file, {
                            contentType: mediaFile.fileType, // Add this line
                            upsert: true // Add this to overwrite if file exists
                        });

                    if (error) {
                        throw error;
                    }

                    // Get public URL
                    const { data: urlData } = supabase.storage
                        .from('media')
                        .getPublicUrl(filePath);

                    console.log(`Upload successful for ${upload.mediaType}, URL: ${urlData.publicUrl}`);

                    // Send to Telegram (this would typically be done via a backend API)
                    // For this example, we'll just log it
                    console.log(`[TELEGRAM] Sending ${upload.mediaType} to donor ${upload.donorId}: ${urlData.publicUrl}`);

                    // Update donor record with media URL
                    // This would typically update your backend database
                    console.log(`[API] Updated donor ${upload.donorId} with ${upload.mediaType} URL`);

                    // Remove from pending uploads in IndexedDB
                    await removePendingUploadById(db, upload.id);

                } catch (uploadError) {
                    console.error(`Error processing upload ${upload.id}:`, uploadError);
                }
            }

            // Refresh pending uploads list from IndexedDB
            const items = await getAllPendingUploads(db);
            setPendingUploads(items);

        } catch (error) {
            console.error('Error syncing pending uploads:', error);
        } finally {
            setIsSyncing(false);
        }
    }, [isOffline, db, isSyncing, pendingUploads]);

    // Attempt to sync whenever we're online and have pending uploads
    useEffect(() => {
        if (!isOffline && db && pendingUploads.length > 0 && !isSyncing) {
            syncPendingUploads();
        }
    }, [isOffline, db, pendingUploads.length, isSyncing, syncPendingUploads]);

    // API is empty for now since we're using direct API calls
    const api = {};

    return (
        <OfflineContext.Provider value={{
            isOffline,
            queueMediaUpload,
            pendingUploads,
            isSyncing,
            syncPendingUploads,
            supabase,
            api
        }}>
            {children}
        </OfflineContext.Provider>
    );
};

export const useOffline = () => {
    const context = useContext(OfflineContext);
    if (context === undefined) {
        throw new Error('useOffline must be used within an OfflineProvider');
    }
    return context;
};
